mapper.select:
SELECT eq.equipe_id, administrateur, nom_equipe
FROM app.equipe as eq
          JOIN app.est_dans as membre ON membre.equipe_id = eq.equipe_id
WHERE eq.equipe_id = #{equipeId}
  AND eq.administrateur = #{administrateur}
  AND eq.nom_equipe = #{nomEquipe}
  AND membre.equipe_id = #{equipeId}

SELECT equipe_id, administrateur, nom_equipe
FROM app.equipe
WHERE equipe_id = #{equipeId}
